#!/bin/sh
# 静态库：ar 打包目标文件，链接时按需抽取
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > add.c << 'EOF'
int add(int a, int b)
{
    return a + b;
}
EOF

cat > mul.c << 'EOF'
int mul(int a, int b)
{
    return a * b;
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int add(int, int);
int mul(int, int);

int main(void)
{
    printf("add(3, 4) = %d\n", add(3, 4));
    printf("mul(3, 4) = %d\n", mul(3, 4));
    return 0;
}
EOF

gcc -c add.c -o add.o
gcc -c mul.c -o mul.o
ar rcs libmath.a add.o mul.o   # r=插入 c=创建 s=建索引
nm libmath.a                   # 归档内每个成员的符号
gcc -c main.c -o main.o
gcc main.o -L. -lmath -o app   # -L. 库目录，-lmath -> libmath.a
./app
